class UriPartsDialog extends AModuleDialog {

    /* indexes of the parts of a parsed (still encoded) query parameter */
    private static final int NAME = 0;
    private static final int VALUE = 1;
    private static final int RAW = 2;

    private LinearLayout box;

/**
 * Splits an encoded query (without the leading '?' nor the fragment) into its parameters.
 * The splitting is done on the encoded string, so that encoded separators ('%26' and '%3D')
 * are kept as part of the name/value instead of being treated as separators.
 * Each element is a {@code [name, value, raw]} array, still encoded.
 */
private static List<String[]> splitQuery(String encodedQuery) {
    var parameters = new ArrayList<String[]>();
    if (encodedQuery == null || encodedQuery.isEmpty()) return parameters;
    var start = 0;
    while (start <= encodedQuery.length()) {
        // find this parameter
        var end = encodedQuery.indexOf('&', start);
        if (end == -1) end = encodedQuery.length();
        var raw = encodedQuery.substring(start, end);
        // split into name and value (by the first '=', which may not be present)
